import { inheritHostedAgentPauseCapability } from "./manual-pause-credential.js";
import { createPreparedHostedRuntimeAgent, } from "./default-chat-runtime.js";
import { parseSourceIntegrationPolicyManifest } from "../../integrations/source-policy.js";
import { snapshotOwnDataRecords } from "../../security/own-data-record.js";
import { createRuntimePreparationCore, } from "./runtime-preparation-core.js";
/** Trusted-only composition. Project metadata crosses the channel; project modules never load here. */
export function createTrustedRuntimePreparation(input) {
    const policy = parseSourceIntegrationPolicyManifest(snapshotOwnDataRecords(input.sourceIntegrationPolicy));
    const { channel } = input;
    const closeProject = input.closeProject.bind(input);
    const aliases = new Map(input.projectTools.aliases.map(({ name, shortName }) => [shortName, name]));
    const signal = AbortSignal.any([input.signal, channel.signal]);
    const tasks = new Set();
    let closing;
    const project = {
        signal,
        async prepare(agentId, context) {
            const deadline = new AbortController();
            const remaining = context.deadline - Date.now();
            if (remaining <= 0)
                throw new Error("Preparation deadline expired");
            const timer = setTimeout(() => deadline.abort(), remaining);
            try {
                const description = await channel.request("agent.describe", { agentId }, {
                    signal: AbortSignal.any([context.signal, deadline.signal]),
                });
                return {
                    description,
                    localTools: {},
                    toolAliases: aliases,
                    sourceIntegrationPolicy: policy,
                };
            }
            finally {
                clearTimeout(timer);
            }
        },
        instantiate: (options, runtimeOptions) => createPreparedHostedRuntimeAgent({
            ...options,
            runtimeAgentId: options.options.agentId,
        }, runtimeOptions),
        retainTask(task) {
            const retained = task.then(() => { }, () => { });
            tasks.add(retained);
            void retained.then(() => tasks.delete(retained));
        },
        close() {
            closing ??= (async () => {
                while (tasks.size > 0)
                    await Promise.all(tasks);
                await closeProject();
            })();
            return closing;
        },
    };
    inheritHostedAgentPauseCapability(project, input);
    return createRuntimePreparationCore({
        binding: input.binding,
        source: input.source,
        grant: input.grant,
        facades: input.facades,
        projectTools: input.projectTools,
        project,
    });
}
